import heapq


def _ledger(data, sequence_first, discounted):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = ((seq, event.get("revision", 0), pos) if sequence_first
               else (event.get("revision", 0), pos))
        if ident not in chosen or key > chosen[ident][0]:
            chosen[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n, d):
        return (n + d // 2) // d if mode == "half_up" else n // d

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        base = net if discounted else raw
        tax = rounded(base * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_component_01():
    return lambda data: _ledger(data, True, True)


def _build_component_02():
    return lambda data: _ledger(data, False, False)


def _build_component_03():
    return lambda data: _ledger(data, True, False)


def _build_component_04():
    return lambda data: _ledger(data, False, True)


def _build_component_05():
    return lambda data: _ledger(data, True, True)


def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        # Enumerating version-or-absent vectors in sorted lexicographic order
        # directly implements the specified global tie-break.
        choices = []
        for name in names:
            versions = sorted(row["version"] for row in packages[name])
            choices.append([-1] + versions)

        for vector in product(*choices):
            installed = {name: version for name, version in zip(names, vector)
                         if version != -1}
            if any(name not in installed for name in roots):
                continue
            if any(name in installed and installed[name] in blocked.get(name, [])
                   for name in names):
                continue
            if any(name in installed and installed[name] != version
                   for name, version in pins.items()):
                continue

            rows_by_name = {}
            for name, version in installed.items():
                rows_by_name[name] = next((row for row in packages[name]
                                           if row["version"] == version), None)
            edges = {name: [] for name in installed}
            valid = True
            for name, row in rows_by_name.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    version = installed.get(other)
                    if version is None or not dep["min"] <= version <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            # Every selected package must belong to the active closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges[name])
            if reachable != set(installed):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if all(visit(name) for name in installed):
                return {"versions": installed}
        return {"error": "unsatisfiable"}
    return solve


def _build_component_07():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        options = [job for job in data["jobs"] if job["id"] not in blocked]
        best_value = None
        best_ids = None
        for subset in combinations(options, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            valid = True
            for group, bounds in data.get("quotas", {}).items():
                count = counts.get(group, 0)
                if not bounds[0] <= count <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i - 1]["end"] > ordered[i]["start"]
                   for i in range(1, len(ordered))):
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and selected < best_ids)):
                best_value, best_ids = value, selected
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        initial = (source, initial_mask, data["coupons"])
        dist = {initial: data["start"]}
        queue = [(data["start"], source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full and remaining == 0:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], remaining)]
                if remaining:
                    options.append((max(2, edge["duration"] - edge.get("discount", 0)),
                                    remaining - 1))
                for duration, left in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    next_mask = mask | bit.get(dest, 0)
                    next_state = (dest, next_mask, left)
                    if arrival < dist.get(next_state, float("inf")):
                        dist[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, next_mask, left))
        return {"arrival": None}
    return solve


